// Stage B: retention prune ----------------------------------------------------
// (web spine events prune through SpineStore.PruneEventsBySource, on the engine)
// Object keys for stale snapshots - deleted from object storage before the rows.
func (q *Queries) LensSnapshotBlobKeysBefore(ctx context.Context, before time.Time) ([]sql.NullString, error) {
	rows, err := q.db.QueryContext(ctx, lensSnapshotBlobKeysBefore, before)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []sql.NullString{}
	for rows.Next() {
		var blob_key sql.NullString
		if err := rows.Scan(&blob_key); err != nil {
			return nil, err
		}
		items = append(items, blob_key)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

